import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import ReactQuill from "react-quill";
import 'react-quill/dist/quill.snow.css';

export default function AdminExtraCurricular() {
  const [sections, setSections] = useState({}); // ✅ safe initialization
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchSections = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/extracurricular");
        setSections(res.data.data?.sections || {});
      } catch {
        toast.error("Failed to fetch content");
      } finally {
        setLoading(false);
      }
    };
    fetchSections();
  }, []);

  const handleChange = (key, value) => {
    setSections(prev => ({
      ...prev,
      [key]: { ...prev[key], content: value }
    }));
  };

  const saveChanges = async () => {
    try {
      await axios.put("http://localhost:5000/api/extracurricular", { sections });
      toast.success("Sections updated successfully!");
    } catch {
      toast.error("Failed to save changes");
    }
  };

  if (loading) return <p>Loading...</p>;

  return (
    <div className="admin-extra-page">
      <Toaster />
      <h2>Admin: Edit Extra Curricular Sections</h2>
      {Object.keys(sections).map((key) => (
        <div key={key} style={{ marginBottom: "20px" }}>
          <h3>{sections[key].title}</h3>
          <ReactQuill
            theme="snow"
            value={sections[key].content}
            onChange={(val) => handleChange(key, val)}
          />
        </div>
      ))}
      <button onClick={saveChanges} style={{ marginTop: "20px", padding: "10px 20px" }}>
        Save Changes
      </button>
    </div>
  );
}
